def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def countIndependentSets(tree):
    MOD = 10 ** 9 + 7
    val, left, right = parse(tree)
    n = len(val)
    inc = [1] * n
    exc = [1] * n
    for u in range(n - 1, -1, -1):
        a = b = 1
        for c in (left[u], right[u]):
            if c != -1:
                a = a * exc[c] % MOD
                b = b * (inc[c] + exc[c]) % MOD
        inc[u] = a
        exc[u] = b
    return (inc[0] + exc[0]) % MOD
